"use client"

import { useState, useMemo } from "react"
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table"
import { Button } from "@/components/ui/button"
import { Pencil } from "lucide-react"

type Props = {
  data: any[];
  onEdit: (row: any, index: number) => void;
}

export default function RecordsTable({ data, onEdit }: Props) {
  const [sortConfig, setSortConfig] = useState<{ key: string; direction: "asc" | "desc" } | null>(null)
  const [currentPage, setCurrentPage] = useState(1)
  const [pageSize, setPageSize] = useState(8) // ✅ default 8

  const sortedData = useMemo(() => {
    if (!sortConfig) return data
    return [...data].sort((a, b) => {
      const valA = a[sortConfig.key as keyof typeof a] ?? ""
      const valB = b[sortConfig.key as keyof typeof b] ?? ""
      if (valA < valB) return sortConfig.direction === "asc" ? -1 : 1
      if (valA > valB) return sortConfig.direction === "asc" ? 1 : -1
      return 0
    })
  }, [data, sortConfig])

  const totalPages = Math.ceil(sortedData.length / pageSize)

  const paginatedData =
    pageSize === 8
      ? sortedData.slice((currentPage - 1) * pageSize, currentPage * pageSize)
      : sortedData

  const handleSort = (key: string) => {
    setSortConfig((prev) =>
      prev?.key === key
        ? { key, direction: prev.direction === "asc" ? "desc" : "asc" }
        : { key, direction: "asc" }
    )
  }

  return (
    <>
      <div
        className={`rounded-md border ${
          pageSize !== 8 ? "max-h-[400px] overflow-y-auto" : "overflow-x-auto"
        }`}
      >
        <Table className="w-full">
          <TableHeader>
            <TableRow className="bg-gray-50">
              <TableHead>Action</TableHead>
              {["firstName", "lastName", "phone", "email", "address", "city", "zip"].map((key) => (
                <TableHead
                  key={key}
                  className="cursor-pointer select-none"
                  onClick={() => handleSort(key)}
                >
                  {key.charAt(0).toUpperCase() + key.slice(1)}
                  {sortConfig?.key === key ? (sortConfig.direction === "asc" ? " ↑" : " ↓") : ""}
                </TableHead>
              ))}
            </TableRow>
          </TableHeader>

          <TableBody>
            {paginatedData.map((row, index) => (
              <TableRow
                key={index}
                className="hover:bg-gray-50 transition-colors"
              >
                <TableCell className="py-1 px-2 text-sm">
                  <Button size="icon" variant="ghost" className="h-6 w-6">
                    <Pencil className="h-3 w-3 text-gray-600" />
                  </Button>
                </TableCell>
                <TableCell className="py-2.5 px-2 text-sm">{row.firstName}</TableCell>
                <TableCell className="py-2.5 px-2 text-sm">{row.lastName}</TableCell>
                <TableCell className="py-2.5 px-2 text-sm">{row.phone}</TableCell>
                <TableCell className="py-2.5 px-2 text-sm">{row.email}</TableCell>

                <TableCell
                  className="truncate max-w-[200px] py-2.5 px-2 text-sm"
                  title={row.address}
                >
                  {row.address}
                </TableCell>

                <TableCell className="py-2.5 px-2 text-sm">{row.city}</TableCell>
                <TableCell className="py-2.5 px-2 text-sm">{row.zip}</TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </div>

      <div className="flex flex-col md:flex-row items-center justify-between mt-4 text-sm text-gray-600 gap-2">
        <div className="flex items-center gap-2">
          <span>Show</span>
          <select
            className="border rounded px-2 py-1 text-sm"
            value={pageSize}
            onChange={(e) => {
              setPageSize(Number(e.target.value))
              setCurrentPage(1)
            }}
          >
            <option value={8}>8</option>
            <option value={10}>10</option>
            <option value={20}>20</option>
          </select>
          <span>entries</span>
        </div>

        {pageSize === 8 && (
          <>
            <div>{`${(currentPage - 1) * pageSize + 1}-${Math.min(
              currentPage * pageSize,
              sortedData.length
            )} of ${sortedData.length}`}</div>
            <div className="flex items-center gap-2">
              <Button
                variant="outline"
                size="sm"
                disabled={currentPage === 1}
                onClick={() => setCurrentPage((p) => p - 1)}
              >
                {"<"}
              </Button>
              <Button
                variant="outline"
                size="sm"
                disabled={currentPage === totalPages}
                onClick={() => setCurrentPage((p) => p + 1)}
              >
                {">"}
              </Button>
            </div>
          </>
        )}
      </div>
    </>
  )
}
